jm={j['id']:i for i,j in enumerate(js)}
elig=[[pi for pi,p in enumerate(ps) if j['tonnage']<=p['tonnage']] for j in js]
rt=[[(-(-j['strokes']//p['strokes_per_minute'])) if pi in elig[ji] else 10**9 for pi,p in enumerate(ps)] for ji,j in enumerate(js)]
def cost(pi,s):
 p=ps[pi];clock=0;fam=p['initial_family'];v=0
 for ji in s:
  j=js[ji];ch=setup[fam][j['family']];cs=clear_of(clock,ch,p['maintenance']);st=clear_of(max(cs+ch,j['release']),rt[ji][pi],p['maintenance']);clock=st+rt[ji][pi];v+=sc*ch+j['weight']*max(0,clock-j['due']);fam=j['family']
 return v
def tc(ss):return sum(cost(i,s) for i,s in enumerate(ss))
def save(ss,v):
 json.dump({'presses':{ps[i]['id']:[js[x]['id'] for x in ss[i]] for i in range(P)}},open(sp,'w'),indent=1);print('SAVE',v,flush=True)
ss=[[jm[x] for x in raw['presses'].get(p['id'],[])] for p in ps];best=tc(ss);bs=[x[:] for x in ss];print('start',best,flush=True)
random.seed(N*991+7);end=time.time()+secs

def best_insert(curcosts,seqs,ji):
 bestx=None; second=10**30
 for pi in elig[ji]:
  s=seqs[pi];old=curcosts[pi]
  for pos in range(len(s)+1):
   nc=cost(pi,s[:pos]+[ji]+s[pos:]);d=nc-old
   if bestx is None or d<bestx[0]:
    if bestx is not None:second=min(second,bestx[0])
    bestx=(d,pi,pos,nc)
   elif d<second:second=d
 return bestx,second

def repair(seqs, removed, regret=False):
 cs=[cost(i,s) for i,s in enumerate(seqs)]
 left=removed[:]
 while left:
  if regret and len(left)<=18:
   opts=[]
   for ji in left:
    bx,snd=best_insert(cs,seqs,ji);opts.append((snd-bx[0],-bx[0],ji,bx))
   _,_,ji,bx=max(opts)
  else:
   ji=left[0];bx,_=best_insert(cs,seqs,ji)
  _,pi,pos,nc=bx;seqs[pi].insert(pos,ji);cs[pi]=nc;left.remove(ji)
 return sum(cs)

def relocate_descent(seqs,cur,limit):
 while time.time()<limit:
  bestmove=None
  cs=[cost(i,s) for i,s in enumerate(seqs)]
  order=list(range(P));random.shuffle(order)
  for a in order:
   sa=seqs[a]
   for ia,ji in list(enumerate(sa)):
    basea=sa[:ia]+sa[ia+1:];ca=cost(a,basea)
    for b in elig[ji]:
     sb=basea if b==a else seqs[b];oldb=ca if b==a else cs[b]
     for pos in range(len(sb)+1):
      if b==a and pos==ia:continue
      nc=cost(b,sb[:pos]+[ji]+sb[pos:]);delta=(nc-oldb)+(ca-cs[a] if b!=a else 0)
      if delta<0 and (bestmove is None or delta<bestmove[0]):bestmove=(delta,a,ia,b,pos)
   if time.time()>=limit:break
