 else:
  # remove contiguous chunks across presses
  removed=[]
  while len(removed)<k:
   pi=random.randrange(P)
   if not cand[pi]:continue
   st=random.randrange(len(cand[pi]));removed.extend(cand[pi][st:st+random.randint(2,6)])
  removed=list(dict.fromkeys(removed))[:k]
 rset=set(removed);cand=[[x for x in s if x not in rset] for s in cand]
 # due/random/weighted order, regret sometimes
 style=random.randrange(5)
 if style==0:removed.sort(key=lambda x:(js[x]['due'],-js[x]['weight']))
 elif style==1:removed.sort(key=lambda x:(js[x]['release'],js[x]['due']))
 elif style==2:removed.sort(key=lambda x:(js[x]['family'],js[x]['due']))
 elif style==3:random.shuffle(removed)
 c=repair(cand,removed,regret=(style==4))
 if c<best:
  bs,best=cand,c;save(bs,best)
  c=relocate_descent(bs,best,min(end,time.time()+secs*.08));best=c;save(bs,best)
 if iters%20==0:print('iter',iters,'best',best,flush=True)
print('FINAL',best,'iters',iters,flush=True);save(bs,best)
